4	function Chart({ plan }) {
5	  const n = plan.duration_assessment.months;
6	  const a = plan.after_shock;
7	  // Stacked scenarios with different durations come with the month-by-month path; otherwise it's a straight line.
8	  const vals = plan.duration_assessment.buffer_path
9	    ?? Array.from({ length: n + 1 }, (_, i) => a.buffer + i * (a.income - a.spending));
10	  const hi = Math.max(1, ...vals);
11	  const lo = Math.min(0, ...vals);
12	  const y = v => 20 + ((hi - v) / (hi - lo)) * 240;
13	  const x = i => 20 + (i / n) * 360;
14	  return (
15	    <div className="chart">
16	      <h3>Buffer through the scenario</h3>
17	      <small>Approximation from rounded API values. Negative values represent unfunded spending, not approved borrowing.</small>
18	      <svg viewBox="0 0 400 300" role="img" aria-label={`Projected buffer over ${n} months`}>
19	        <line x1="20" y1={y(0)} x2="380" y2={y(0)} stroke="#cbd6ca" strokeDasharray="4" />
20	        <polyline points={vals.map((v, i) => `${x(i)},${y(v)}`).join(' ')} fill="none" stroke="#1c594b" strokeWidth="3" />
21	        <circle cx="380" cy={y(vals[n])} r="4" fill="#f0854e" />
22	        <text x="20" y="292" fontSize="12" fill="#65746d">Now</text>
23	        <text x="380" y="292" fontSize="12" fill="#65746d" textAnchor="end">Month {n}</text>
24	      </svg>
25	    </div>
26	  );
27	}
