29	function Explanation({ state }) {
30	  let body;
31	  if (!state || state.loading) body = <p>Preparing the explanation…</p>;
32	  else if (state.error) body = `Calculations are available. Explanation unavailable: ${state.error}`;
33	  else {
34	    const t = state.data;
35	    body = (
36	      <>
37	        <h3>What this means</h3><p>{t.summary}</p>
38	        <h3>Your goal</h3><p>{t.goal_plan_text}</p>
39	        <h3>Contingency plan</h3><p>{t.backup_plan_text}</p>
40	        {t.caveat && <p className="warning">{t.caveat}</p>}
41	        <small>Explanation source: {t.source}</small>
42	      </>
43	    );
44	  }
45	  return <div id="explanation" className="explanation">{body}</div>;
46	}
