50	// Children stay direct descendants of #results: the Plan view's CSS hides all but .action-plans and .explanation.
51	function PlanResults({ c }) {
52	  const p = c.plan;
53	  const b = c.baseline;
54	  const a = p.after_shock;
55	  const d = p.duration_assessment;
56	  const rows = [
57	    ['Monthly inflows', cash(p.baseline.income), cash(a.income)],
58	    ['Monthly spending', cash(p.baseline.spending), cash(a.spending)],
59	    ['Buffer after immediate costs', cash(p.baseline.buffer), cash(a.buffer)],
60	    ['Monthly shortfall', cash(Math.max(b.spending - b.income, 0)), cash(a.monthly_gap)],
61	    ['Runway', runway(p.baseline), runway(a)],
62	    ['Immediate expense', '—', cash(a.one_off_costs || 0)],
63	  ];
64	  return (
65	    <>
66	      <table className="comparison">
67	        <thead><tr><th>Account {c.account}</th><th>Before</th><th>After</th></tr></thead>
68	        <tbody>{rows.map(r => <tr key={r[0]}><td>{r[0]}</td><td>{r[1]}</td><td>{r[2]}</td></tr>)}</tbody>
69	      </table>
70	      {d && (
71	        <div className={'outcome' + (d.covers_duration ? '' : ' danger')}>
72	          <h3>{d.covers_duration ? 'Covered' : 'Funding gap'} over {d.months} months</h3>
73	          <p>{d.assumption}</p>
74	          <div className="mini-grid">
75	            <Mini label="Required starting buffer" value={cash(d.required_starting_buffer)} />
76	            <Mini label="Additional buffer needed" value={cash(d.additional_buffer_needed)} />
77	          </div>
78	        </div>
79	      )}
80	      {/* With a chart: chart ~60% wide, the four cards stacked on its right. Without: the usual 2x2 grid. */}
81	      <div className={d ? 'impact-row' : undefined}>
82	        {d && <Chart plan={p} />}
83	        <div className="mini-grid">
84	          <Mini label="Required monthly spending reduction" value={cash(p.backup_plan.monthly_cut_needed)} />
85	          <Mini label="Immediate funding needed" value={cash(p.backup_plan.upfront_funding_needed)} />
86	          <Mini label="Emergency-fund target" value={cash(p.goal_plan.target_amount)} />
87	          <Mini label="Time to goal at baseline surplus" value={p.goal_plan.months_to_goal === null ? 'Not reachable' : p.goal_plan.months_to_goal + ' months'} />
88	        </div>
89	      </div>
90	      {p.action_plan && (
91	        <ActionPlan key={c.planVersion} plan={p} planning={c.planning} busy={c.busy} error={c.planningError} onSubmit={c.recalculatePlan} />
92	      )}
93	      <Explanation state={c.explanation} />
94	      <details className="data">
95	        <summary>Inspect all calculated values and account data</summary>
96	        <pre>{JSON.stringify({ account: b, plan: p }, null, 2)}</pre>
97	      </details>
98	      <p className="fine-print">Amounts are displayed as whole dollars. Estimates are scenario inputs, not observed category budgets.</p>
99	    </>
100	  );
101	}
