15	export default function App() {
16	  const c = useCushion();
17	  const [view, setView] = useState('start');
18	  const [mode, setMode] = useState(readMode);
19	  const [accountInput, setAccountInput] = useState(String(c.account));
20	  const isAdmin = mode === 'admin';
21	  // Only admins can browse the account list; customers land on their own snapshot.
22	  const home = isAdmin ? 'users' : 'customer';
23	  const tabs = isAdmin ? TABS : TABS.filter(([v]) => v !== 'users');
24	
25	  // The stylesheet switches layouts on body[data-view=...].
26	  useEffect(() => { document.body.dataset.view = view; }, [view]);
27	
28	  function show(next) {
29	    setView(VIEWS.includes(next) && (isAdmin || next !== 'users') ? next : home);
30	    window.scrollTo({ top: 0, behavior: 'instant' });
