32	
33	  function toggleMode() {
34	    const next = isAdmin ? 'user' : 'admin';
35	    setMode(next);
36	    try { localStorage.setItem(MODE_KEY, next); } catch { /* per-viewer convenience only */ }
37	    if (next === 'user' && view === 'users') setView('customer');
38	  }
39	
40	  function openAccount(id) {
41	    setAccountInput(String(id));
42	    if (!c.busy) c.loadAccount(id);
43	    show('customer');
44	  }
45	
46	  return (
47	    <>
48	      {view === 'start' && <Welcome onDone={() => show(home)} />}
49	      <div id="app-shell" hidden={view === 'start'}>
50	        <header>
51	          <a className="brand" href="/" aria-label="Cushion home" onClick={e => { e.preventDefault(); show(home); }}>
52	            <img className="brand-pillow" src="/pillow.PNG" alt="" /> Cushion
53	          </a>
54	          <span className="header-note">TANGERINE / RESILIENCE REWIRED</span>
55	          <button type="button" className="mode-switch" role="switch" aria-checked={isAdmin}
56	            aria-label="Admin mode" onClick={toggleMode}>
57	            <span className="mode-label">{isAdmin ? 'Admin' : 'Customer'}</span>
58	            <span className="mode-track" aria-hidden="true"><span className="mode-thumb" /></span>
59	          </button>
60	        </header>
61	        <nav className="cushion-tabs" aria-label="Workspace">
62	          {tabs.map(([v, label]) => (
63	            <button key={v} type="button" aria-current={view === v ? 'page' : undefined} onClick={() => show(v)}>{label}</button>
64	          ))}
65	        </nav>
66	        {isAdmin && <UserDatabase hidden={view !== 'users'} ids={c.accountIds} onOpen={openAccount} />}
67	        <Dashboard
68	          hidden={view === 'users'}
69	          view={view}
70	          show={show}
71	          isAdmin={isAdmin}
72	          c={c}
73	          accountInput={accountInput}
74	          setAccountInput={setAccountInput}
75	        />
76	      </div>
77	    </>
78	  );
79	}
