1	import { useCallback, useEffect, useRef, useState } from 'react';
2	import { api } from './format.js';
3	
4	const GREETING = 'What would you like to stress-test? I’ll ask for an estimate if the account data doesn’t identify a cost.';
5	const REPLACED = 'This interpretation has been replaced. Use the latest scenario.';
6	const DEFAULT_ACCOUNT = 20134;
7	const STACKED = 'Builds on your applied scenario: these changes are added to the ones already applied, and each keeps its own duration.';
8	export const MAX_STACKED = 10;  // matches ShockModel.parts max_length in the API
9	
10	// Stack a new shock on top of the one already applied, so scenarios are cumulative. Each shock stays a
11	// separate part with its own duration; the engine applies each part only during its own window.
12	export function combineShocks(prev, next) {
13	  return { shock: { parts: [...(prev.parts?.length ? prev.parts : [prev]), next] }, notes: [STACKED] };
14	}
15	
16	const recentKey = id => 'runway:recentQueries:' + id;
17	function readRecent(id) {
18	  try {
19	    const saved = JSON.parse(sessionStorage.getItem(recentKey(id)) || '[]');
20	    return Array.isArray(saved) ? saved.filter(q => typeof q === 'string' && q.trim() && q.length <= 500).slice(0, 2) : [];
21	  } catch { return []; }
22	}
