24	// All app state and the API workflow: load an account, interpret a shock, clarify, apply, re-plan.
25	export function useCushion() {
26	  const [health, setHealth] = useState('Connecting…');
27	  const [accountIds, setAccountIds] = useState([]);
28	  const [account, setAccount] = useState(DEFAULT_ACCOUNT);
29	  const [baseline, setBaseline] = useState(null);
30	  const [plan, setPlan] = useState(null);
31	  const [planVersion, setPlanVersion] = useState(0);
32	  const [planning, setPlanning] = useState({});
33	  const [explanation, setExplanation] = useState(null);
34	  const [messages, setMessages] = useState([]);
35	  const [recentQueries, setRecentQueries] = useState([]);
36	  const [busy, setBusyState] = useState(false);
37	  const [pageError, setPageError] = useState('');
38	  const [planningError, setPlanningError] = useState('');
39	  const [manualOpen, setManualOpen] = useState(false);
40	
41	  // Values read synchronously inside async handlers (React state would be stale there).
42	  const s = useRef({
43	    account: DEFAULT_ACCOUNT, busy: false, revision: 0, planToken: 0, appliedShock: null, planning: {},
44	    amounts: {}, duration: null, incomePct: null, overlap: false, recent: [],
45	  }).current;
46	  const nextId = useRef(0);
47	
48	  const setBusy = on => { s.busy = on; setBusyState(on); };
49	  const resetClarifications = () => { s.amounts = {}; s.duration = null; s.incomePct = null; s.overlap = false; };
50	
51	  const addMessage = msg => setMessages(m => [...m, { id: ++nextId.current, ...msg }]);
52	  const say = (text, extra = {}) => addMessage({ kind: 'text', text, ...extra });
53	  const markDone = id => setMessages(m => m.map(x => (x.id === id ? { ...x, done: true } : x)));
54	  // A reviewable scenario is shown (and applied) on top of whatever is already applied.
55	  const interpretation = result => {
56	    if (result.status === 'ok' && result.shock && s.appliedShock) {
57	      if ((s.appliedShock.parts?.length || 1) >= MAX_STACKED) {
58	        say(`You can stack up to ${MAX_STACKED} changes. Load the account again to start a new scenario.`);
59	        return;
60	      }
61	      const { shock, notes } = combineShocks(s.appliedShock, result.shock);
62	      result = { ...result, shock, added: result.shock, assumptions: [...(result.assumptions || []), ...notes] };
63	    }
64	    addMessage({ kind: 'interp', result, revision: s.revision, done: false });
65	  };
66	
67	  function showPlan(p) {
68	    const token = ++s.planToken;
69	    setPlan(p);
70	    setPlanVersion(v => v + 1);
71	    setExplanation({ loading: true });
72	    api('/api/explain', p)
73	      .then(t => { if (token === s.planToken) setExplanation({ data: t }); })
74	      .catch(e => { if (token === s.planToken) setExplanation({ error: e.message }); });
75	  }
76	
77	  const loadAccount = useCallback(async id => {
78	    setBusy(true);
79	    setPageError('');
80	    try {
81	      const b = await api(`/api/accounts/${id}/baseline`);
82	      s.account = id;
83	      s.recent = readRecent(id);
84	      s.appliedShock = null;
85	      s.planning = {};
86	      s.revision++;
87	      s.planToken++;
88	      resetClarifications();
89	      setAccount(id);
90	      setRecentQueries(s.recent);
91	      setBaseline(b);
92	      setPlan(null);
93	      setPlanning({});
94	      setExplanation(null);
95	      setPlanningError('');
96	      setMessages([{ id: ++nextId.current, kind: 'text', text: GREETING }]);
97	    } catch (e) {
98	      setPageError(e.message);
99	    } finally {
100	      setBusy(false);
101	    }
102	  }, []); // eslint-disable-line react-hooks/exhaustive-deps
103	
104	  useEffect(() => {
105	    (async () => {
106	      try {
107	        const h = await api('/api/health');
108	        setHealth(h.gemini_enabled ? 'Gemini configured · local data' : 'Manual mode · Gemini disabled');
109	        const ids = await api('/api/accounts');
110	        setAccountIds(ids.account_ids);
111	      } catch {
112	        setHealth('Connection unavailable');
113	      }
114	      await loadAccount(DEFAULT_ACCOUNT);
115	    })();
116	  }, [loadAccount]);
117	
118	  function rememberQuery(text) {
119	    s.recent = [text, ...s.recent].slice(0, 2);
120	    try { sessionStorage.setItem(recentKey(s.account), JSON.stringify(s.recent)); } catch { /* storage unavailable */ }
121	    setRecentQueries(s.recent);
122	  }
123	
124	  // morphFrom: the text box's on-screen rectangle, so the sent message can animate out of it.
125	  async function sendQuery(text, morphFrom) {
126	    if (s.busy) return;
127	    s.revision++;
128	    rememberQuery(text);
129	    say(text, { user: true, morphFrom });
130	    resetClarifications();
131	    setBusy(true);
132	    try {
133	      const r = await api('/api/parse-shock', { account_id: s.account, text });
134	      if (['ok', 'needs_input'].includes(r.status)) interpretation(r);
135	      else {
136	        say(r.message || 'No usable change was found. Try a more specific scenario.');
137	        if (r.status === 'error') setManualOpen(true);
138	      }
139	    } catch (e) {
140	      say(e.message);
141	    } finally {
142	      setBusy(false);
143	    }
144	  }
145	
146	  function submitManual(f) {
147	    if (s.busy) return;
148	    const duration = Number(f.get('duration'));
149	    const change = Number(f.get('recurring'));
150	    const oneoff = Number(f.get('oneoff'));
151	    s.revision++;
152	    say('Manual scenario entered. Please review the amounts before applying.', { user: true });
153	    interpretation({
154	      status: 'ok',
155	      interpretation: 'All changes are held constant during the selected assessment window.',
156	      assumptions: change ? ['Recurring amount is a user-supplied change, already net of the existing category cost.'] : [],
157	      shock: {
158	        income_multiplier: Number(f.get('income')) / 100,
159	        income_duration_months: duration,
160	        scenario_duration_months: duration,
161	        household_bills_pct_change: Number(f.get('bills')),
162	        one_off_costs: oneoff ? [{ label: 'Immediate expense', amount_dollars: oneoff }] : [],
163	        recurring_costs: change ? [{ label: f.get('label'), monthly_change: change, source: 'user_estimate' }] : [],
164	      },
165	    });
166	  }
167	
168	  async function clarify(msg, fd) {
169	    if (s.busy) return;
170	    if (msg.revision !== s.revision) { say(REPLACED); return; }
171	    for (const [k, v] of fd) {
172	      if (k.startsWith('amount_')) s.amounts[k.slice(7)] = Number(v);
173	      if (k === 'duration') s.duration = Number(v);
174	      if (k === 'incomePct') s.incomePct = Number(v);
175	      if (k === 'overlap') s.overlap = true;
176	    }
177	    setBusy(true);
178	    try {
179	      const r = await api('/api/resolve-shock', {
180	        account_id: s.account, draft: msg.result.draft, category_amounts: s.amounts, duration_months: s.duration,
181	        income_replacement_pct: s.incomePct, overlap_acknowledged: s.overlap,
182	      });
183	      markDone(msg.id);
184	      interpretation(r);
185	    } catch (e) {
186	      say(e.message);
187	    } finally {
188	      setBusy(false);
189	    }
190	  }
191	
192	  async function applyScenario(msg) {
193	    if (s.busy) return;
194	    if (msg.revision !== s.revision) { say(REPLACED); return; }
195	    const shock = msg.result.shock;
196	    const choices = {
197	      target_months: s.planning.target_months ?? 3,
